import { Graph } from "#core/ui/graph-layout/graph.js";
import { VisitedElement } from "#core/ui/graph-layout/layout-ranker.js";

// eslint-disable-next-line @typescript-eslint/no-namespace -- grandfathered code
export namespace graphAlgo {
	export function postorder(g: Graph, vs: string[]): string[] {
		return dfs(g, vs, "post");
	}

	export function preorder(g: Graph, vs: string[]): string[] {
		return dfs(g, vs, "pre");
	}

	/*
	 * A helper that performs a pre- or post-order traversal on the input graph
	 * and returns the nodes in the order they were visited. If the graph is
	 * undirected then this algorithm will navigate using neighbors. If the graph
	 * is directed then this algorithm will navigate using successors.
	 *
	 * Order must be one of "pre" or "post".
	 */
	function dfs(g: Graph, vs: string[], order: string): string[] {
		if (!Array.isArray(vs)) {
			vs = [vs];
		}

		const navigation = (g.isDirected() ? g.successors : g.neighbors).bind(g);

		const acc: string[] = [];
		const visited: VisitedElement = {};
		vs.forEach((v) => {
			if (!g.hasNode(v)) {
				throw new Error("Graph does not have node: " + v);
			}

			doDfs(g, v, order === "post", visited, navigation, acc);
		});

		return acc;
	}

	function doDfs(
		g: Graph,
		v: string,
		postorder: boolean,
		visited: VisitedElement,
		navigation: (v: string) => undefined | string[],
		acc: string[],
	) {
		if (visited[v] == undefined) {
			visited[v] = true;

			if (!postorder) {
				acc.push(v);
			}

			const navigationResult: string[] | undefined = navigation(v);

			if (navigationResult != undefined) {
				navigationResult.forEach((w) => {
					doDfs(g, w, postorder, visited, navigation, acc);
				});
			}
			if (postorder) {
				acc.push(v);
			}
		}
	}
}
